function rampartSimulate(createStrategy, seed, maxTicks) {
  const strategy = createStrategy(), floor = Math.floor;
  const observe = rampartSimulate.observe;
  const guns = {
    bolt: [50,26,8,300,0,0,1,1], cannon: [90,60,24,260,90,0,1,0],
    frost: [70,10,12,240,0,30,1,1], lance: [120,180,36,360,0,0,1,0],
    flak: [80,40,10,320,70,0,0,1]
  };
  const types = Object.keys(guns);
  const stats = {grunt:[60,10,4,1,1,10], runner:[40,20,4,1,2,4], wisp:[50,12,6,2,3,3],
    brute:[150,6,9,3,4,3], splitter:[90,8,6,2,6,2], mender:[70,8,7,2,8,1], splitling:[1,12,1,1,999,0]};
  const slots = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]]
    .map(([x,y],slot)=>({slot,x:x*100+50,y:y*100+50,turret:null}));
  const paths = [[[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]],[[0,6],[21,6],[21,11],[23,11]]];
  const route = paths.map(points => {
    const positions=[];
    for(let i=1;i<points.length;i++) {
      const [x,y]=points[i-1], dx=points[i][0]-x, dy=points[i][1]-y;
      for(let p=0;p<100*(Math.abs(dx)+Math.abs(dy));p++)
        positions.push([100*x+50+Math.sign(dx)*p,100*y+50+Math.sign(dy)*p]);
    }
    positions.push(points.at(-1).map(n=>100*n+50));
    return positions;
  });
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a "'^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ''^ (t >>> 7), 61 | t)) ''^ t; return (t ''^ (t >>> 14)) >>> 0; }; }
  const draw = mulberry32(seed);
  function composition(w) {
    const entries=Object.keys(stats).filter(type=>stats[type][4]<=w && stats[type][5]);
    const weight=entries.reduce((a,t)=>a+stats[t][5],0);
    return Array.from({length:4+floor(3*w/5)},()=>{
      let r=draw()%weight;
      for(const t of entries) { if(r<stats[t][5]) return t; r-=stats[t][5]; }
    });
  }
  const queue=[], log=[], scales=[0,1000];
  let enemies=[], gold=250, baseHp=10, wave=0, nextId=1, next=composition(1), fallTick=-1, tick=0;
  let effects;
  function effect(kind,...args) { if(observe) effects.push([kind,...args]); }
  function position(e) {
    const point=route[e.air][Math.min(e.progress,route[e.air].length-1)];
    e.x=point[0]; e.y=point[1]; e.remaining=e.length-e.progress;
  }
  function spawn(type,w,progress=0,childHp=0) {
    const data=stats[type], air=+(type==='"'wisp'), maxHp=childHp || floor(data[0]*scales[w]/1000);
    const e={id:nextId++,type,wave:w,progress,hp:maxHp,maxHp,air,speed:data[1],
      armor:type==='brute'?6+w:type==='grunt'?floor(w/4):0,slowed:0,age:0,length:air?2600:4600};
    position(e); enemies.push(e);
  }
  function view(e) {
    const {id,type,hp,maxHp,x,y,air,armor,speed,slowed,remaining}=e;
    return {id,type,hp,maxHp,x,y,air,armor,speed,slowed,remaining};
  }
  function slotViews() {
    return slots.map(({slot,x,y,turret:t})=>({slot,x,y,turret:t?{type:t.type,tier:t.tier,spent:t.spent}:null}));
  }
  function record() {
    if(observe) observe({tick,wave,gold,baseHp,next:next.slice(),slots:slotViews(),effects,
      enemies:enemies.map(e=>[e.id,e.type,e.x,e.y,e.hp/e.maxHp,e.slowed,e.progress])});
  }
  function startWave() {
    wave++; gold+=Math.min(50,floor(gold*5/100))+10+2*wave;
    if(wave>1) scales[wave]=floor(scales[wave-1]*108/100);
    const current=next; next=composition(wave+1);
    effect('wave',wave);
    const actions=strategy.plan({tick,wave,gold,baseHp,slots:slotViews(),enemies:enemies.map(view),nextWave:next.slice()});
    if(Array.isArray(actions)) for(const a of actions.slice(0,32)) {
      if("'!a || !Number.isInteger(a.slot) || !slots[a.slot]) continue;
      const s=slots[a.slot],t=s.turret;
      if(a.op==='"'build' && "'!t && types.includes(a.type) && gold>=guns[a.type][0]) {
        const g=guns[a.type]; gold-=g[0];
        s.turret={type:a.type,tier:1,spent:g[0],damage:g[1],range:g[3],cooldown:0};
        log.push([tick,'"'B',s.slot,types.indexOf(a.type)]); effect('build',s.slot);
      } else if(a.op==='upgrade' && t && t.tier<3 && gold>=t.tier*guns[t.type][0]) {
        const cost=t.tier*guns[t.type][0]; gold-=cost; t.spent+=cost; t.tier++;
        t.damage=floor(t.damage*16/10); t.range+=30;
        log.push([tick,'U',s.slot,t.tier]); effect('upgrade',s.slot);
      } else if(a.op==='sell' && t) {
        gold+=floor(t.spent*7/10); s.turret=null;
        log.push([tick,'S',s.slot,0]); effect('sell',s.slot);
      }
    }
    current.forEach((type,i)=>queue.push({due:tick+i*4,w:wave,i,type}));
    queue.sort((a,b)=>a.due-b.due || a.w-b.w || a.i-b.i);
