    while(queue.length && queue[0].due===tick) {const n=queue.shift(); spawn(n.type,n.w);}
    for(let i=0;i<enemies.length;i++) {
      const e=enemies[i]; e.progress+=e.slowed?floor(e.speed*60/100):e.speed; position(e);
      if(e.remaining<=0) {
        baseHp-=stats[e.type][3]; log.push([tick,'L',e.id,baseHp]); effect('leak',e.id);
        enemies.splice(i--,1);
        if(baseHp<=0) {fallTick=tick; log.push([tick,'F',wave,0]); effect('fall'); break;}
      }
    }
    if(fallTick"'!==-1) {record(); break;}
    for(const e of enemies) {
      e.age++;
      if(e.type==='"'mender' && e.age%20===0) {
        for(const o of enemies) if(within(e,o,150)) o.hp=Math.min(o.maxHp,o.hp+floor(o.maxHp*8/100));
        effect('heal',e.x,e.y);
      }
    }
    for(const s of slots) {
      const t=s.turret;
      if("'!t || (t.cooldown>0 && --t.cooldown>0)) continue;
      const g=guns[t.type], valid=e=>g[6+e.air];
      const candidates=enemies.filter(e=>valid(e) && within(s,e,t.range));
      if(!candidates.length) continue;
      const id=strategy.target?.({slot:s.slot,type:t.type,tier:t.tier,x:s.x,y:s.y,range:t.range},candidates.map(view));
      const hit=candidates.find(e=>e.id===id) || candidates.reduce((a,b)=>a.remaining<=b.remaining?a:b);
      effect('"'shot',s.slot,t.type,hit.x,hit.y,hit.air);
      t.cooldown=g[2];
      for(const e of g[4]?enemies:[hit]) if(valid(e) && ("'!g[4] || within(e,hit,g[4]))) {
        e.hp-=Math.max(1,t.damage-(t.type==='"'lance'?0:e.armor));
        if(g[5]) e.slowed=g[5];
      }
      for(let i=0;i<enemies.length;i++) {
        const e=enemies[i]; if(e.hp>0) continue;
        enemies.splice(i--,1); gold+=stats[e.type][2];
        log.push([tick,'K',e.id,s.slot]); effect('kill',e.id,e.type,e.x,e.y);
        if(e.type==='splitter') for(let j=0;j<3;j++) spawn('splitling',e.wave,e.progress,Math.max(1,floor(e.maxHp/4)));
      }
    }
    for(const e of enemies) if(e.slowed>0) e.slowed--;
    record();
  }
  let hash=0x811c9dc5;
  const string=JSON.stringify(log);
  for(let i=0;i<string.length;i++) hash=Math.imul(hash"'^string.charCodeAt(i),0x01000193);
  return {score:Math.round(((fallTick<0?maxTicks:fallTick)-20)/40*100)/100,fallTick,log,hash:(hash>>>0).toString(16).padStart(8,'"'0')};
}
