function createStrategy() {
  const battery=[0,2,4,8,11,6,3,1,13,9,7], antiAir=[14,5,10,15,12];
  const cost={bolt:50,cannon:90,frost:70,lance:120,flak:80};
  const power=[0,1,1.6,2.56];
  const futureStats={"grunt":[60,10,1],"runner":[40,20,1],"brute":[150,6,3],"wisp":[50,12,2],"splitter":[90,8,2],"mender":[70,8,2]};
  let known=[],scale=1000;
  // A short tactical forecast prices a fully funded battery conversion in the last sector.
  // Income and new construction beyond the current payment are intentionally excluded.
  const routes=[[[50,250],[650,250],[650,1050],[1250,1050],[1250,350],[1850,350],[1850,1150],[2350,1150]],[[50,650],[2150,650],[2150,1150],[2350,1150]]];
  const tracks=routes.map(nodes=>{
    const points=[];
    for(let i=1;i<nodes.length;i++){
      const [x,y]=nodes[i-1],dx=nodes[i][0]-x,dy=nodes[i][1]-y;
      for(let n=0;n<Math.abs(dx)+Math.abs(dy);n++)points.push([x+n*Math.sign(dx),y+n*Math.sign(dy)]);
    }
    return points;
  });
  const tables={bolt:[26,8,300,0],lance:[180,36,360,0],flak:[40,10,320,70],cannon:[60,24,260,90],frost:[10,12,240,0]};
  function forecast(state,layout,swap=-1,replacement='') {
    const es=state.enemies.map(e=>({...e,p:tracks[e.air].length-e.remaining}));
    let penalty=0,children=0; let maxId=0;for(const e of es)maxId=Math.max(maxId,e.id);
    const guns=layout.map((t,i)=>{
      if(!t)return null;
      const type=i===swap?replacement:t.type,tier=i===swap?3:t.tier;
      const [damage,period,baseRange,blast]=tables[type],range=baseRange+30*(tier-1);
      return {x:state.slots[i].x,y:state.slots[i].y,type,damage:Math.floor(damage*power[tier]),cd:i===swap?0:(i*7)%period,period,range2:range*range,blast};
    });
    const harm=e=>e.type==='brute'?3:(e.air||e.type==='mender'||e.type==='splitter')?2:1;
    const horizon=190;
    for(let step=1;step<=horizon;step++){
      if((step-1)%4===0){
        const ix=(step-1)/4, type=known[ix%known.length]||'grunt', d=futureStats[type], air=+(type==='wisp'), hp=Math.floor(d[0]*scale/1000);
        es.push({id:++maxId,type,p:0,remaining:tracks[air].length,x:0,y:0,air,hp,maxHp:hp,armor:type==='brute'?6+state.wave:type==='grunt'?Math.floor(state.wave/4):0,speed:d[1],slowed:0});
      }
      for(const e of es) {
        if(e.hp<=0)continue;
